type obj = map[string]any

// pyQuote is json.dumps(s, ensure_ascii=True).
func pyQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\r':
			b.WriteString(`\r`)
		case r == '\t':
			b.WriteString(`\t`)
		case r == '\b':
			b.WriteString(`\b`)
		case r == '\f':
			b.WriteString(`\f`)
		case r < 0x20 || r >= 0x7f && r <= 0xffff:
			fmt.Fprintf(&b, `\u%04x`, r)
		case r > 0xffff:
			r -= 0x10000
			fmt.Fprintf(&b, `\u%04x\u%04x`, 0xd800+(r>>10), 0xdc00+(r&0x3ff))
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

var (
	syntaxText = regexp.MustCompile(`[^\n]* \(<unknown>, line (\d+)\)`)
	addrText   = regexp.MustCompile(` at 0x[0-9a-f]+`)
)

// norm hides CPython's wording of a parse error (keeping its line) and
// memory addresses, which are not graded.
func norm(s string) string {
	s = syntaxText.ReplaceAllString(s, "<syntax error> (<unknown>, line $1)")
	return addrText.ReplaceAllString(s, " at 0x?")
}

func q(s string) string { return pyQuote(norm(s)) }

// pyJSONList is json.dumps(list_of_str).
func pyJSONList(items []string) string {
	parts := make([]string, len(items))
	for i, s := range items {
		parts[i] = pyQuote(s)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// decode turns a case value into a Python value: plain JSON for null,
// booleans, small integers, strings and lists, one-key objects for the rest.
func decode(v any) asteval.Value {
	switch x := v.(type) {
	case nil:
		return asteval.None()
	case bool:
		return asteval.Bool(x)
	case json.Number:
		n, _ := new(big.Int).SetString(string(x), 10)
		return asteval.BigInt(n)
	case string:
		return asteval.String(x)
	case []any:
		items := make([]asteval.Value, len(x))
		for i, it := range x {
			items[i] = decode(it)
		}
		return asteval.List(items...)
	case map[string]any:
		for tag, val := range x {
			switch tag {
			case "i":
				n, _ := new(big.Int).SetString(val.(string), 10)
				return asteval.BigInt(n)
			case "f":
				return asteval.Float(hexFloat(val.(string)))
			case "c":
				p := val.([]any)
				return asteval.Complex(complex(hexFloat(p[0].(string)), hexFloat(p[1].(string))))
			case "b":
				var out []byte
				h := val.(string)
				for i := 0; i+1 < len(h); i += 2 {
					c, _ := strconv.ParseUint(h[i:i+2], 16, 8)
					out = append(out, byte(c))
				}
				return asteval.Bytes(out)
			case "t":
				items := []asteval.Value{}
				for _, it := range val.([]any) {
					items = append(items, decode(it))
				}
				return asteval.Tuple(items...)
			case "d":
				var keys, vals []asteval.Value
				for _, pair := range val.([]any) {
					kv := pair.([]any)
					keys = append(keys, decode(kv[0]))
					vals = append(vals, decode(kv[1]))
				}
				d, err := asteval.NewDict(keys, vals)
				if err != nil {
					panic(err)
				}
				return d
			}
		}
	}
	panic(fmt.Sprintf("unknown case value %v", v))
}

// hexFloat parses float.hex() output (and inf, -inf, nan).
func hexFloat(s string) float64 {
	switch s {
	case "inf":
		return math.Inf(1)
	case "-inf":
		return math.Inf(-1)
	case "nan":
		return math.NaN()
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil && !strings.Contains(err.Error(), "range") {
		panic(err)
	}
	return f
}

func symbols(v any) []asteval.Symbol {
	var out []asteval.Symbol
	for _, pair := range v.([]any) {
		kv := pair.([]any)
		out = append(out, asteval.Symbol{Name: kv[0].(string), Value: decode(kv[1])})
	}
	return out
}

func options(o obj, w, ew *bytes.Buffer) asteval.Options {
	opts := asteval.DefaultOptions()
	opts.Writer, opts.ErrWriter = w, ew
	if v, ok := o["nested"].(bool); ok {
		opts.NestedSymtable = v
	}
	if v, ok := o["minimal"].(bool); ok {
		opts.Minimal = v
	}
	if v, ok := o["readonly"].([]any); ok {
		opts.ReadonlySymbols = []string{}
		for _, s := range v {
			opts.ReadonlySymbols = append(opts.ReadonlySymbols, s.(string))
		}
	}
	if v, ok := o["builtins_readonly"].(bool); ok {
		opts.BuiltinsReadonly = v
	}
	if v, ok := o["config"].([]any); ok {
		opts.Config = map[string]bool{}
		for _, pair := range v {
			kv := pair.([]any)
			opts.Config[kv[0].(string)] = kv[1].(bool)
		}
	}
	if v, ok := o["max_len"].(json.Number); ok {
		n, _ := v.Int64()
		opts.MaxStatementLength = int(n)
	}
	if v, ok := o["user_symbols"]; ok {
		opts.UserSymbols = symbols(v)
	}
	if v, ok := o["flags"].([]any); ok {
		for _, pair := range v {
			kv := pair.([]any)
			opts.NodeFlags = append(opts.NodeFlags, asteval.NodeFlag{Name: kv[0].(string), Value: kv[1].(bool)})
		}
	}
	if v, ok := o["symtable"]; ok {
		var keys, vals []asteval.Value
		for _, s := range symbols(v) {
			keys = append(keys, asteval.String(s.Name))
			vals = append(vals, s.Value)
		}
		d, err := asteval.NewDict(keys, vals)
		if err != nil {
			panic(err)
		}
		opts.Symtable = d
	}
	return opts
}

func reprLine(v asteval.Value) string {
	s, err := asteval.Repr(v)
	if err != nil {
		return "R! " + excParts(err)
	}
	return "R " + q(s)
}

func excParts(err error) string {
	if e, ok := err.(*asteval.Exception); ok {
		return e.Class + " " + q(e.Msg)
	}
	return "GoError " + q(err.Error())
}

func errorLines(in *asteval.Interpreter, view string) []string {
	errs := in.Errors()
	if view == "first" {
		if len(errs) == 0 {
			return []string{"X1 -"}
		}
		return []string{"X1 " + errs[0].Class() + " " + q(errs[0].Msg())}
	}
	out := []string{fmt.Sprintf("X %d", len(errs))}
	for _, e := range errs {
		_, text := e.GetError()
		out = append(out, "X "+e.Class()+" "+q(e.Msg())+" "+q(text))
	}
	return out
}

// quiet runs fn with the process's standard output discarded: what the
// library prints there is not graded.
func quiet(fn func()) {
	saved := os.Stdout
	null, err := os.OpenFile(os.DevNull, os.O_WRONLY, 0)
	if err == nil {
		os.Stdout = null
		defer func() {
			os.Stdout = saved
			null.Close()
		}()
	}
	fn()
}

// evalLines runs one eval or run step and returns its lines.
func evalLines(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, run func() (asteval.Value, error)) []string {
	var r asteval.Value
	var err error
	quiet(func() { r, err = run() })
	var out []string
	if err == nil {
		out = append(out, reprLine(r))
	}
	out = append(out, "W "+q(w.String()), "E "+q(ew.String()))
	w.Reset()
	ew.Reset()
	out = append(out, errorLines(in, view)...)
	if err != nil {
		out = append(out, "RAISE "+excParts(err))
	}
	return out
}

func flag(step obj, name string, def bool) bool {
	if v, ok := step[name].(bool); ok {
		return v
	}
	return def
}

func opEval(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	lineno := 0
	if v, ok := step["lineno"].(json.Number); ok {
		n, _ := v.Int64()
		lineno = int(n)
	}
	*out = append(*out, evalLines(in, step, view, w, ew, func() (asteval.Value, error) {
		return in.Eval(step["src"].(string), lineno, flag(step, "show", true), flag(step, "raise", false))
	})...)
}

func opRun(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	*out = append(*out, evalLines(in, step, view, w, ew, func() (asteval.Value, error) {
		tree, err := in.Parse(step["src"].(string))
		if err != nil {
			return nil, err
		}
		return in.Run(tree, flag(step, "raise", true))
	})...)
}

func opSym(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	for _, n := range step["names"].([]any) {
		name := n.(string)
		v, ok := in.Lookup(name)
		if !ok {
			*out = append(*out, "S "+name+" -")
			continue
		}
		s, err := asteval.Repr(v)
		if err != nil {
			*out = append(*out, "S "+name+" ! "+excParts(err))
			continue
		}
		*out = append(*out, "S "+name+" "+q(s))
	}
}

func opNames(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	*out = append(*out, "N "+q(pyJSONList(in.UserDefinedSymbols())))
}

func opValid(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	for _, n := range step["names"].([]any) {
		name := n.(string)
		res := "False"
		if asteval.ValidSymbolName(name) {
			res = "True"
		}
		*out = append(*out, "V "+q(name)+" "+res)
	}
}

func opASTNames(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	tree, err := in.Parse(step["src"].(string))
	if err != nil {
		cls := "GoError"
		if e, ok := err.(*asteval.Exception); ok {
			cls = e.Class
		}
		*out = append(*out, "A! "+cls)
		return
	}
	*out = append(*out, "A "+q(pyJSONList(asteval.GetASTNames(tree))))
}

func opMakeTable(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	var kws []asteval.Symbol
	if v, ok := step["kws"]; ok {
		kws = symbols(v)
	}
	table := asteval.MakeSymbolTable(flag(step, "nested", false), kws)
	s, err := asteval.Repr(table)
	if err != nil {
		*out = append(*out, "T! "+excParts(err))
		return
	}
	*out = append(*out, "T "+q(s))
}

func runCase(c obj) []string {
	var w, ew bytes.Buffer
	o, _ := c["opts"].(obj)
	in := asteval.New(options(o, &w, &ew))
	view, _ := c["view"].(string)
	if view == "" {
		view = "full"
	}
	var out []string
	for _, s := range c["steps"].([]any) {
		step := s.(obj)
		runOp(in, step, view, &w, &ew, &out)
	}
	return out
}

func runOp(in *asteval.Interpreter, step obj, view string, w, ew *bytes.Buffer, out *[]string) {
	switch step["op"] {
	case "astnames":
		opASTNames(in, step, view, w, ew, out)
	case "eval":
		opEval(in, step, view, w, ew, out)
	case "maketable":
		opMakeTable(in, step, view, w, ew, out)
	case "names":
		opNames(in, step, view, w, ew, out)
	case "run":
		opRun(in, step, view, w, ew, out)
	case "sym":
		opSym(in, step, view, w, ew, out)
	case "valid":
		opValid(in, step, view, w, ew, out)
	}
}

// TestRecordedCases replays cases recorded from the Python original (asteval
// at the base commit, under CPython 3.12) and compares every printed line.
func TestRecordedCases(t *testing.T) {
	f, err := os.Open(filepath.Join("testdata", "recorded.jsonl"))
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	n := 0
	for sc.Scan() {
		var rec struct {
			Case  json.RawMessage `json:"case"`
			Lines []string        `json:"lines"`
		}
		if err := json.Unmarshal(sc.Bytes(), &rec); err != nil {
			t.Fatal(err)
		}
		dec := json.NewDecoder(bytes.NewReader(rec.Case))
		dec.UseNumber()
		var c obj
		if err := dec.Decode(&c); err != nil {
			t.Fatal(err)
		}
		got := runCase(c)
		if len(got) != len(rec.Lines) {
			t.Errorf("%s: printed %d lines, want %d", c["id"], len(got), len(rec.Lines))
			continue
		}
		for i := range got {
			if got[i] != rec.Lines[i] {
				t.Errorf("%s line %d:\n got  %s\n want %s", c["id"], i, got[i], rec.Lines[i])
			}
		}
		n++
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	if n == 0 {
		t.Fatal("no recorded cases")
	}
}
